-- Focused fixture of the supplied schema: real rows, constraints and balance view.
create role anon;create role authenticated;create role service_role;
create function myb_stable_uuid(t text) returns uuid language sql immutable as $$select md5(coalesce(t,''))::uuid$$;
create table families(id uuid primary key,sync_code text unique,name text not null default 'Mẹ Yêu Bé',deleted_at timestamptz);
create table devices(id uuid primary key,family_id uuid not null references families(id),device_name text,device_type text,platform text,app_version text,last_seen_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table health_members(id uuid primary key,family_id uuid not null references families(id),relation text,created_at timestamptz not null default now(),deleted_at timestamptz);
create table milk_containers(id uuid primary key,family_id uuid not null references families(id),legacy_id text,name text not null,kind text,color text,capacity_ml numeric,active boolean not null default true,sort_order int default 0,extra jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table care_events(id uuid primary key,family_id uuid not null references families(id),member_id uuid references health_members(id) on delete set null,legacy_id text,type text not null,event_date date,time_from text,time_to text,amount numeric,unit text,source text,status text,note text,extra jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version int not null default 1,created_by_device uuid references devices(id) on delete set null,updated_by_device uuid references devices(id) on delete set null,last_op_id uuid,deleted_at timestamptz);
create table pump_events(id uuid primary key,family_id uuid not null references families(id),care_event_id uuid not null references care_events(id) on delete cascade,side text,amount_ml numeric,duration_min int,storage text,container_id uuid,container_kind text,container_name text,expire_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table milk_items(id uuid primary key,family_id uuid not null references families(id),pump_event_id uuid references pump_events(id) on delete set null,short_code text,container_id uuid references milk_containers(id) on delete set null,container_kind text,container_name text,storage text,amount_ml numeric not null default 0,expire_at timestamptz,status text not null default 'storing',note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version int not null default 1,created_by_device uuid references devices(id),updated_by_device uuid references devices(id),last_op_id uuid,deleted_at timestamptz,legacy_id text,remaining_ml numeric,legacy_status text,extra jsonb not null default '{}');
create table feed_events(id uuid primary key,family_id uuid not null references families(id),care_event_id uuid not null references care_events(id) on delete cascade,feed_type text,milk_type text,actual_ml numeric,taken_ml numeric,wasted_ml numeric,formula_brand text,count_as_feed boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table feed_milk_sources(id uuid primary key,family_id uuid not null references families(id),feed_event_id uuid not null references feed_events(id) on delete cascade,milk_item_id uuid not null references milk_items(id) on delete restrict,used_ml numeric not null default 0,discard_ml numeric not null default 0,remainder_action text default 'keep',order_index int default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table milk_transactions(id uuid primary key,family_id uuid not null references families(id),milk_item_id uuid not null references milk_items(id) on delete cascade,care_event_id uuid references care_events(id) on delete set null,transaction_type text not null,ml numeric not null default 0,reason text,created_at timestamptz not null default now(),created_by_device uuid references devices(id),deleted_at timestamptz,updated_at timestamptz not null default now());
create table sleep_events(id uuid primary key,family_id uuid not null references families(id),care_event_id uuid not null references care_events(id) on delete cascade,sleep_from timestamptz,sleep_to timestamptz,duration_min int,quality text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table diaper_events(id uuid primary key,family_id uuid not null references families(id),care_event_id uuid not null references care_events(id) on delete cascade,wet boolean default false,dirty boolean default false,stool_color text,stool_amount text,note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table temperature_events(id uuid primary key,family_id uuid not null references families(id),care_event_id uuid not null references care_events(id) on delete cascade,temperature_c numeric,measure_place text,note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table myb_realtime_events(id bigint generated by default as identity primary key,family_id uuid not null references families(id),event_kind text not null default 'relational_write',created_at timestamptz not null default now());
create function myb_set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create function myb_emit_relational_realtime_v1577() returns trigger language plpgsql security definer as $$begin insert into myb_realtime_events(family_id) values(new.family_id);return new;end$$;
create trigger signal after insert or update of last_seen_at on devices for each row execute function myb_emit_relational_realtime_v1577();
do $$declare t text;begin foreach t in array array['care_events','devices','milk_items','milk_containers','feed_events','feed_milk_sources','pump_events','sleep_events','diaper_events','temperature_events'] loop execute format('create trigger updated before update on %I for each row execute function myb_set_updated_at()',t);execute format('alter table %I enable row level security',t);end loop;end$$;
create view milk_item_balances as select m.id milk_item_id,m.family_id,m.amount_ml,
 greatest(0,m.amount_ml+coalesce(sum(case when t.transaction_type in('feed_use','discard','transfer_out') then -t.ml when t.transaction_type in('transfer_in','adjust') then t.ml else 0 end) filter(where t.deleted_at is null),0)) remaining_ml
 from milk_items m left join milk_transactions t on t.milk_item_id=m.id where m.deleted_at is null group by m.id;
-- Minimal non-care shell and exact care/milk section markers from production.
create function myb_relational_export_state_v1576(p_sync_id text default 'main') returns jsonb language plpgsql security definer set search_path=public as $$
declare v_care jsonb;v_milk jsonb;v_cont jsonb;begin
 select coalesce(jsonb_agg(coalesce(ce.extra,'{}')||myb_care_doc_v1540(ce)),'[]') into v_care from care_events ce where family_id=myb_stable_uuid('family:'||p_sync_id) and deleted_at is null;
 select coalesce(jsonb_agg(myb_milk_doc_v1540(mi)),'[]') into v_milk from milk_items mi where family_id=myb_stable_uuid('family:'||p_sync_id) and deleted_at is null;
 select coalesce(jsonb_agg(coalesce(mc.extra,'{}')||jsonb_build_object('id',legacy_id,'kind',kind,'name',name,'capacity',capacity_ml,'active',active)),'[]') into v_cont from milk_containers mc where family_id=myb_stable_uuid('family:'||p_sync_id) and deleted_at is null;
 return jsonb_build_object('ok',true,'family_id',myb_stable_uuid('family:'||p_sync_id),'payload',jsonb_build_object('careEvents',v_care,'milkInventory',v_milk,'milkContainers',v_cont));end$$;
-- Legacy metadata/lock sequence used to verify the production lock-order patch.
create function myb_relational_apply_changes_v1576(p_sync_id text,p_device_key text,p_changes jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_family_id uuid:=myb_stable_uuid('family:'||p_sync_id);begin
 insert into public.families(id,sync_code) values(v_family_id,p_sync_id) on conflict(id) do update set sync_code=excluded.sync_code;
 perform pg_advisory_xact_lock(hashtextextended('myb-v1576:' || v_family_id::text,0));
 return jsonb_build_object('ok',true);end$$;
create function myb_catalog_write_v1530(p_sync_id text,p_kind text,p_op text,p_id text,p_data jsonb,p_expected jsonb,p_device_key text) returns jsonb language plpgsql as $$declare state jsonb;begin state:=public.myb_relational_export_state_v1576(p_sync_id)::jsonb;return state;end$$;
insert into families(id,sync_code) values(myb_stable_uuid('family:main'),'main'),(myb_stable_uuid('family:other'),'other');
insert into milk_containers(id,family_id,legacy_id,name,kind,capacity_ml) values(myb_stable_uuid('milk_container:main:b1'),myb_stable_uuid('family:main'),'b1','Bottle 1','binh',500),(myb_stable_uuid('milk_container:main:b2'),myb_stable_uuid('family:main'),'b2','Bottle 2','binh',500),(myb_stable_uuid('milk_container:main:t1'),myb_stable_uuid('family:main'),'t1','Bag','tui',0);
